const R=window.RESEARCH,M=window.METRICS,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='all',activeId=null,edits={},editLog=[];
try{edits=JSON.parse(localStorage.getItem('scoutby-edits-v1')||'{}');editLog=JSON.parse(localStorage.getItem('scoutby-log-v1')||'[]');if(!edits||typeof edits!=='object'||Array.isArray(edits))edits={};if(!Array.isArray(editLog))editLog=[]}catch{}
const badge=u=>`<span class="badge ${u==='Авария'?'emergency':u==='Срочно'?'urgent':'normal'}">${esc(u)}</span>`;
function showPage(id){if(!['journal','research','try','method'].includes(id))id='journal';document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===id));history.replaceState(null,'','#'+id);window.scrollTo(0,0)}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));window.addEventListener('hashchange',()=>showPage(location.hash.slice(1)));showPage(location.hash.slice(1)||'journal');
$('#diffCount').textContent=M.disagreements.length;$('#emergencyCount').textContent=M.b.all.emergencies;$('#reviewCount').textContent=M.review;
for(const c of Triage.categories)$('#category').add(new Option(c,c));for(const h of HOUSES)$('#newHouse').add(new Option(h.id+' · ввод '+h.commission,h.commission));
function filtered(){const q=$('#search').value.toLowerCase().replace(/^[oо]-/,'о-'),method=$('#methodSelect').value;return R.filter(r=>{const p=r[method];return(!q||[r.id,r.text,r.house_code].join(' ').toLowerCase().includes(q))&&(!$('#category').value||p.category===$('#category').value)&&(!$('#urgency').value||p.urgency===$('#urgency').value)&&(view==='all'||view==='diff'&&r.disagreement||view==='review'&&r.review||view==='done'&&edits[r.id])})}
function render(){const items=filtered(),method=$('#methodSelect').value;$('#rows').innerHTML=items.length?items.map(r=>{const p=r[method];return `<tr data-id="${r.id}"><td><b>${r.id}</b><small>${r.date}</small></td><td><span class="excerpt">${esc(r.text)}</span><small>${r.house_code}${r.injection?' · вложенное указание ИИ':''}</small></td><td>${esc(p.category)}${p.additional?'<small>+ '+esc(p.additional)+'</small>':''}</td><td>${badge(p.urgency)}${r.disagreement?'<div class="row-note">A ≠ B</div>':''}${edits[r.id]?'<div class="row-note">Есть моё решение</div>':''}</td><td>${esc(p.recipient)}${r.date_issue?'<small>Проверить дату</small>':''}</td><td><button class="row-open" aria-label="Открыть ${r.id}">↗</button></td></tr>`}).join(''):'<tr><td colspan="6" class="empty-row">Обращений по этим условиям нет. Измените фильтры.</td></tr>';$('#count').textContent=`Показано ${items.length} из 150 · ${$('#methodSelect').selectedOptions[0].text}`;$('#rows').querySelectorAll('tr[data-id]').forEach(row=>row.addEventListener('click',()=>openRecord(row.dataset.id)))}
['search','category','urgency','methodSelect'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));
$('#segments').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;view=b.dataset.view;$('#segments').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));render()});
$('#reset').addEventListener('click',()=>{$('#search').value='';$('#category').value='';$('#urgency').value='';view='all';$('#segments').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x.dataset.view==='all'));render()});
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function csvCell(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
$('#export').addEventListener('click',()=>{const method=$('#methodSelect').value;const rows=[['id','категория','доп. категория','срочность','кому передать','способ'],...filtered().map(r=>[r.id,...['category','additional','urgency','recipient'].map(k=>r[method][k]),method])];download('scoutby_'+method+'_selection.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8')});
$('#exportEdits').addEventListener('click',()=>download('scoutby_my_review.json',JSON.stringify({exported_at:new Date().toISOString(),notice:'Личные решения этого браузера; исходные A/B и аудит не изменены',decisions:edits,history:editLog},null,2),'application/json'));
function openRecord(id){const r=R.find(x=>x.id===id);if(!r)return;activeId=id;$('#detailTitle').textContent=id;const previous=edits[id];const p=previous?.decision||r.reference;
 $('#detailBody').innerHTML=`<div class="detail-meta">${r.date} · ${r.house_code} · Гарантия: ${esc(r.warranty)} · до ${r.warranty_end}</div><div class="source-text">${esc(r.text)}</div><div class="compare">${[['a','A · прямой'],['b','B · по шагам'],['reference','Предварительный аудит']].map(([key,title])=>`<article><h3>${title}</h3>${badge(r[key].urgency)}<p>${esc(r[key].category)}${r[key].additional?'<br>+ '+esc(r[key].additional):''}</p><p>${esc(r[key].recipient)}</p></article>`).join('')}</div><p class="reason">${esc(r.reason)}</p>${r.ambiguous?'<p class="result-warning">Неоднозначный случай. В регламенте недостаточно подробностей для единственного бесспорного ответа.</p>':''}${r.date_issue?'<p class="result-warning">Дата обращения раньше ввода дома. Подтвердите дату и адрес.</p>':''}<form id="editForm" class="edit-form"><h3>Моё решение</h3><div class="edit-grid"><label class="edit-field">Категория<select name="category">${Triage.categories.map(c=>`<option ${c===p.category?'selected':''}>${c}</option>`).join('')}</select></label><label class="edit-field">Дополнительная категория<select name="additional"><option value="">Нет</option>${Triage.categories.map(c=>`<option ${c===p.additional?'selected':''}>${c}</option>`).join('')}</select></label><label class="edit-field">Срочность<select name="urgency">${['Обычная','Срочно','Авария'].map(c=>`<option ${c===p.urgency?'selected':''}>${c}</option>`).join('')}</select></label><label class="edit-field">Кому передать<select name="recipient">${Triage.recipients.map(c=>`<option ${c===p.recipient?'selected':''}>${c}</option>`).join('')}</select></label><label class="edit-field">Обоснование решения<input name="note" maxlength="1000" required value="${esc(previous?.note||'')}" placeholder="Почему вы приняли это решение"></label></div><button class="primary" type="submit">Сохранить моё решение</button><span id="saveStatus" role="status"></span><p class="edit-note">Сохранение только в этом браузере. Каждая правка добавляется в экспортируемую историю; исследовательские результаты не меняются.</p></form>`;
 $('#editForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const decision=Object.fromEntries(['category','additional','urgency','recipient'].map(k=>[k,f.get(k)]));if(decision.category===decision.additional){$('#saveStatus').textContent=' Основная и дополнительная категории должны различаться.';return}const now=new Date().toISOString(),entry={id,decision,note:f.get('note'),at:now};editLog.push({...entry,previous:edits[id]||null});edits[id]=entry;try{localStorage.setItem('scoutby-edits-v1',JSON.stringify(edits));localStorage.setItem('scoutby-log-v1',JSON.stringify(editLog));$('#saveStatus').textContent=' Сохранено в этом браузере.'}catch{$('#saveStatus').textContent=' Хранилище недоступно: решение пока в памяти. Экспортируйте его до закрытия страницы.'}render()});if(!$('#detail').open)$('#detail').showModal();}
$('#closeDetail').addEventListener('click',()=>$('#detail').close());document.querySelectorAll('[data-record]').forEach(b=>b.addEventListener('click',()=>openRecord(b.dataset.record)));
const pct=(n,d)=>(100*n/d).toFixed(1).replace('.',',')+'%';$('#bars').innerHTML=['a','b'].map((k,i)=>`<div class="bar-row"><div class="bar-label"><span>Способ ${k.toUpperCase()}</span><b>${M[k].all.exact}/150 · ${pct(M[k].all.exact,150)}</b></div><div class="bar-track"><div style="width:${100*M[k].all.exact/150}%;background:${i?'#e67b4d':'#93a6ba'}"></div></div></div>`).join('');
$('#metricTable').innerHTML=`<table class="metric-table"><thead><tr><th>Согласованность</th><th>A</th><th>B</th></tr></thead><tbody>${[['Категория','category'],['Доп. категория','additional'],['Срочность','urgency'],['Адресат','recipient']].map(([label,key])=>`<tr><td>${label}</td><td>${M.a.all.fields[key]}/150</td><td>${M.b.all.fields[key]}/150</td></tr>`).join('')}<tr><td>Обнаружено кандидатов в аварии</td><td>${M.a.all.emergency_tp}/12</td><td>${M.b.all.emergency_tp}/12</td></tr><tr><td>Полное совпадение на однозначных строках</td><td>${M.a.unambiguous.exact}/124</td><td>${M.b.unambiguous.exact}/124</td></tr></tbody></table>`;
const examples={smoke:['Из электрощитка в подъезде идёт дым и пахнет гарью.','2026-10-20'],bill:['В квитанции неверная площадь квартиры, 64 вместо 46 м².','2026-10-20'],mixed:['В подъезде грязно, и с утра нет горячей воды во всей квартире.','2026-10-20'],season:['Батареи холодные, дома +20. Когда включат отопление?','2026-07-15']};
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{const e=examples[b.dataset.example];$('#newText').value=e[0];$('#newDate').value=e[1];$('#triageForm').requestSubmit()}));
$('#triageForm').addEventListener('submit',e=>{e.preventDefault();try{const p=Triage.classify($('#newText').value,$('#newDate').value,$('#newHouse').value);$('#triageResult').className='paper result-detail';$('#triageResult').innerHTML=`<div class="eyebrow">ПРЕДВАРИТЕЛЬНЫЙ РАЗБОР ПО ПРАВИЛАМ</div><h2>Нужна проверка диспетчером</h2>${badge(p.urgency)}<dl><dt>Категория</dt><dd>${esc(p.category)}</dd><dt>Дополнительная</dt><dd>${esc(p.additional||'Нет')}</dd><dt>Кому передать</dt><dd>${esc(p.recipient)}</dd></dl><p>${esc(p.reason)}</p>${p.notes.map(x=>'<p class="result-warning">'+esc(x)+'</p>').join('')}<p class="caption">Результат не отправлен службам и не сохранён в общий журнал.</p>`}catch(err){$('#triageResult').textContent=err.message}});
render();
